&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Interpersonal&amp;nbsp;skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
