&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;e654f3c638bc&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;bulletList&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
