&lt;/li&gt;
&lt;li data-local-id=&quot;fd734ffc-1577-46a2-aa2c-bad7386d9d89&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
&lt;p data-local-id=&quot;58d65c8a-1c38-4565-9dce-ff21756b79c4&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Delivery and monitoring: GitLab, GitLab CI, ELK, Datadog&lt;/p&gt;
