&lt;p data-local-id=&quot;acb1f9b2-b44f-4a59-befa-d33c26764f55&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot;&gt;&lt;strong data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;strong&quot;&gt;&lt;span class=&quot;fabric-text-color-mark&quot; data-text-custom-color=&quot;#000000&quot; data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;textColor&quot;&gt;In your role, you will:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;08444a80&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;bulletList&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
&lt;li data-local-id=&quot;35f1c42a&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
