&lt;/li&gt;
&lt;li data-local-id=&quot;5d33074c&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
