&lt;/li&gt;
&lt;li data-local-id=&quot;b4a31f563a33&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
&lt;p data-local-id=&quot;5f783864c428&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Experience working in a product development team with agile practices.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-local-id=&quot;4b3ce22f-67f4-4779-bd39-671aa5b6d2c7&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
