&lt;/li&gt;
&lt;li data-local-id=&quot;349a1706-ce0c-4047-bbd4-b6bdcd0109df&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
