&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Job metadata&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;344120fe-537f-5c41-9dd4-16cebadb2931|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469777841,&amp;quot;Aptos&amp;quot;,469777844,&amp;quot;Aptos&amp;quot;,469769226,&amp;quot;Aptos&amp;quot;,335551500,&amp;quot;7760736&amp;quot;,268442635,&amp;quot;18&amp;quot;,335559740,&amp;quot;257&amp;quot;,201341983,&amp;quot;0&amp;quot;,335559739,&amp;quot;160&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;3&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777842,&amp;quot;&amp;quot;,469777843,&amp;quot;ＭＳ 明朝&amp;quot;,201341986,&amp;quot;1&amp;quot;,469775450,&amp;quot;Job metadata&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;Jobmetadata&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;London (&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Job metadata&quot;&gt;Hybrid) |&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Job metadata&quot;&gt; Technology &amp;amp; &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Job metadata&quot;&gt;Engineering&amp;nbsp; |&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Job metadata&quot;&gt; Permanent&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:257}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;The Role&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt; &lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As a Principal Security Engineer at Capco, you&#39;ll lead hands-on security engineering delivery for clients across financial services and other complex environments. Depending on the engagement, you&#39;ll lead a technical workstream or operate independently as a Principal specialist. Your focus will span Application &amp;amp; Product Security, Cloud &amp;amp; Platform Security and DevSecOps, underpinned by strong security automation. You&#39;ll combine specialist depth with cross-domain judgement, client engagement and secure-by-design engineering.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:100,&amp;quot;335559740&amp;quot;:264}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
